#!/usr/bin/env python3
"""
finish_install_html_rebrand.py

Finishes the co|op rebrand of dashboard/install.html and swaps the
actual downloadable extension zip for the current clean build.

WHAT WAS ALREADY DONE (an earlier script already fixed this, still holds):
  - "Install co|op", "Download co|op", body copy, button text - all
    already correctly branded. Confirmed by reading the live file
    before writing this script.

WHAT THIS SCRIPT FIXES (the remaining gaps):
  1. The logo lockup still showed a shield emoji + "Sy|phir" wordmark
     (the old pre-rebrand logo). Design system says no shield icons
     anywhere - replaced with a plain co|op wordmark, pipe highlighted,
     matching how the mark appears everywhere else on the site.
  2. dashboard/extension/syphir-extension.zip is replaced with
     dashboard/extension/coop-extension.zip - the current clean 9-file
     build (icons + trimmed host_permissions already baked in).
  3. All references to the old filename/folder name in install.html
     are updated to match - including a real bug fix: the new zip has
     no wrapping folder inside it (files sit loose at the root), so
     when someone unzips it, their OS creates a folder named after the
     zip itself. The old instructions said "select the extension
     folder" - that would have been WRONG for this zip's actual
     structure. Now it correctly says "coop-extension".

The zip is embedded below as base64 so this script is self-contained -
nothing else to download or copy over first.

syphir26@gmail.com is left untouched everywhere it appears - that's
the real, intentional contact address, not a branding leftover.

Usage:
    cd /path/to/-syphir     # repo root
    python3 finish_install_html_rebrand.py
"""

import base64
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
INSTALL_PATH = REPO_ROOT / "dashboard" / "install.html"
OLD_ZIP = REPO_ROOT / "dashboard" / "extension" / "syphir-extension.zip"
NEW_ZIP = REPO_ROOT / "dashboard" / "extension" / "coop-extension.zip"

NEW_ZIP_B64 = (
    ""
)

OLD_LOGO = '''  <div class="logo">
    <div class="logo-icon">\U0001F6E1\uFE0F</div>
    <div class="logo-text">Sy<span>phir</span></div>
  </div>'''

NEW_LOGO = '''  <div class="logo">
    <div class="logo-text">co<span>|</span>op</div>
  </div>'''

REPLACEMENTS = [
    (OLD_LOGO, NEW_LOGO, 1),
    (
        'href="/extension/syphir-extension.zip" download="syphir-extension.zip"',
        'href="/extension/coop-extension.zip" download="coop-extension.zip"',
        1,
    ),
    (
        'Find <strong style="color:#e6edf3;">syphir-extension.zip</strong>',
        'Find <strong style="color:#e6edf3;">coop-extension.zip</strong>',
        1,
    ),
    (
        "select the syphir-extension folder",
        "select the <strong>coop-extension</strong> folder",
        1,
    ),
    (
        'you\'ll get a folder called <strong style="color:#e6edf3;">extension</strong>.',
        'you\'ll get a folder called <strong style="color:#e6edf3;">coop-extension</strong>.',
        1,
    ),
    (
        'select the <strong style="color:#e6edf3;">extension</strong> folder — not the zip file',
        'select the <strong style="color:#e6edf3;">coop-extension</strong> folder — not the zip file',
        1,
    ),
]


def fail(msg):
    print(f"\n\u274c ABORTED: {msg}")
    print("Nothing was written.")
    sys.exit(1)


def main():
    print("co|op install.html rebrand finisher")
    print(f"Repo root: {REPO_ROOT}\n")

    if not INSTALL_PATH.exists():
        fail(f"dashboard/install.html not found at {INSTALL_PATH}")

    text = INSTALL_PATH.read_text(encoding="utf-8")

    for old, new, expected in REPLACEMENTS:
        found = text.count(old)
        if found != expected:
            fail(
                f"Expected {expected} occurrence(s) of:\n    {old!r}\n"
                f"but found {found}. install.html may have changed since "
                f"this script was written - stopping before touching anything."
            )

    for old, new, expected in REPLACEMENTS:
        text = text.replace(old, new)

    INSTALL_PATH.write_text(text, encoding="utf-8")
    print(f"\u2713 dashboard/install.html updated ({len(text)} bytes)")

    NEW_ZIP.parent.mkdir(parents=True, exist_ok=True)
    NEW_ZIP.write_bytes(base64.b64decode(NEW_ZIP_B64))
    print(f"\u2713 wrote dashboard/extension/coop-extension.zip ({NEW_ZIP.stat().st_size} bytes)")

    if OLD_ZIP.exists():
        OLD_ZIP.unlink()
        print(f"\u2713 removed old dashboard/extension/syphir-extension.zip")
    else:
        print("  \u2192 old syphir-extension.zip already gone, nothing to remove")

    print("\n\u2705 Done. Nothing was committed or pushed.")
    print("Next: run `git status` / `git diff` to review, then commit/push yourself.")
    print("\nNote: there is also a root-level ./syphir-extension.zip (not the one")
    print("dashboard/extension one) that nothing references - safe to delete")
    print("separately whenever, not touched by this script.")


if __name__ == "__main__":
    main()
